import gurobipy as gp
from gurobipy import GRB

# Assume env is provided externally
model = gp.Model(env=env)

months = [7, 8, 9, 10, 11, 12]
C = 500
INIT_INV = 200

b_price = {7: 28, 8: 24, 9: 25, 10: 27, 11: 23, 12: 23}
s_price = {7: 29, 8: 24, 9: 26, 10: 28, 11: 22, 12: 25}

b_vars = {}
s_vars = {}
I_vars = {}
for m in months:
    b_vars[m] = model.addVar(lb=0, vtype=GRB.INTEGER, name=f"b_{m}")
    s_vars[m] = model.addVar(lb=0, vtype=GRB.INTEGER, name=f"s_{m}")
    I_vars[m] = model.addVar(lb=0, ub=C, vtype=GRB.INTEGER, name=f"I_{m}")

# Inventory recurrence constraints
for i, m in enumerate(months):
    if i == 0:  # month 7
        model.addConstr(I_vars[m] == INIT_INV + b_vars[m] - s_vars[m], name=f"inv_eq_{m}")
    else:
        prev_m = months[i-1]
        model.addConstr(I_vars[m] == I_vars[prev_m] + b_vars[m] - s_vars[m], name=f"inv_eq_{m}")

# Objective: maximize total selling revenue
obj = gp.LinExpr()
for m in months:
    obj += s_price[m] * s_vars[m]
model.setObjective(obj, GRB.MAXIMIZE)

model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
```

